CAMERA_CATALOG = "cameras_catalog.json"
POST_NETWORK_CATALOG = "post_network_catalog.json"
LOCALITY_KMZ = {
    "Puerto Natales": "Puerto Natales.kmz",
    "Porvenir": "Porvenir.kmz",
    "Puerto Williams": "Puerto Williams.kmz",
}


def build_locality_layers(locality: str, filename: str) -> list[dict]:
    """Normalize differently named Earth folders into consistent locality layers."""
    dataset = read_kmz(filename)
    slug = locality.lower().replace(" ", "-")
    buckets: dict[str, dict] = {}

    def category(group_name: str) -> tuple[str, str, str]:
        key = group_name.casefold().replace("ó", "o").replace("á", "a")
        if "poste" in key:
            return "Postes", "Postes", "#ffca28"
        if "tramo_bt" in key or "red bt" in key:
            return "Red BT", "Red BT", "#1646ff"
        if "tramo_mt" in key or "red mt" in key or "alimentador" in key:
            return "Redes MT", "Redes MT", "#ff3030"
        if "transformador" in key or key in {"propiedad empresa", "propiedad particular"}:
            return "Transformadores", "Subestaciones", "#ab47bc"
        if any(token in key for token in ("fusible", "desconect", "reconect", "equipo")):
            return "Equipos", "Equipos", "#26a69a"
        return group_name or "Otros activos", group_name or "Otros activos", "#607d8b"

    for group_name, group in dataset["groups"].items():
        display, source, color = category(group_name)
        bucket = buckets.setdefault(display, {"source": source, "color": color, "points": [], "lines": []})
        bucket["points"].extend([
            {**item, "attributes": {**item.get("attributes", {}), "_SOURCE_GROUP": group_name}}
            for item in group["points"]
        ])
        bucket["lines"].extend(group["lines"])

    layers = []
    order = ["Postes", "Equipos", "Transformadores", "Redes MT", "Red BT"]
    for index, name in enumerate(sorted(buckets, key=lambda value: (order.index(value) if value in order else len(order), value))):
        bucket = buckets[name]
        if not bucket["points"] and not bucket["lines"]:
            continue
        layers.append({
            "id": f"{slug}-{index}",
            "name": name,
            "sourceName": bucket["source"],
            "locality": locality,
            "color": bucket["color"],
            "defaultOn": False,
            "defaultMobileOn": False,
            "data": {"points": bucket["points"], "lines": bucket["lines"], "polygons": []},
        })
    return layers

@st.cache_resource(show_spinner="Preparando las capas del mapa…")
def build_layers_json() -> str:
    network = read_kmz(NETWORK)
    concession_lt = read_kmz(CONCESSION_LT)
    concession_ge = read_kmz(CONCESSION_GE)
    periurbano = read_kmz(PERIURBANO)
    centrality = read_kmz(CENTRALITY)
    post_network_catalog = json.loads((DATA_DIR / POST_NETWORK_CATALOG).read_text(encoding="utf-8"))
    enrich_post_network(network, post_network_catalog)
    enrich_post_network(centrality, post_network_catalog)
    centrality_points, camera_points = split_centrality_cameras(centrality)
    camera_catalog = json.loads((DATA_DIR / CAMERA_CATALOG).read_text(encoding="utf-8"))
    cameras_by_code = {
        str(item.get("attributes", {}).get("IDENTIFICADOR_VNR") or item.get("name") or "").strip().upper(): item
        for item in camera_points
    }
    for catalog_item in camera_catalog:
        code = str(catalog_item.get("attributes", {}).get("IDENTIFICADOR_VNR") or catalog_item.get("name") or "").strip().upper()
        if code in cameras_by_code:
            existing = cameras_by_code[code]
            existing["attributes"] = {**existing.get("attributes", {}), **catalog_item.get("attributes", {})}
        else:
            new_item = {**catalog_item, "centrality_group": "Camaras", "description": "Catálogo de nodos EDELMAG"}
            camera_points.append(new_item)
            cameras_by_code[code] = new_item
    layers = [
        {"id": "network-" + str(i), "name": name,
         "locality": "Punta Arenas", "defaultOn": True, "defaultMobileOn": name == "Postes",
         "color": {"Equipos": "#26a69a", "Postes": "#ffca28", "Subestaciones": "#ab47bc", "Redes MT": "#ff3030", "Red BT": "#1646ff"}.get(name, "#607d8b"),
         "data": {"points": group["points"], "lines": group["lines"], "polygons": []}}
        for i, (name, group) in enumerate(network["groups"].items())
        if group["points"] or group["lines"]
    ]
    layers += [
        {"id": "lt15", "name": "Concesión menor a 15", "locality": "Zonas de concesión", "color": "#26c6da",
         "data": {"points": [], "lines": [], "polygons": concession_lt["polygons"]}},
        {"id": "ge14", "name": "Concesión GEO superior a 14", "locality": "Zonas de concesión", "color": "#ff7043",
         "data": {"points": [], "lines": [], "polygons": concession_ge["polygons"]}},
    ]

    layers += [{
        "id": "periurbano",
        "name": "Redes municipales",
        "locality": "Punta Arenas",
        "color": "#ffd21f",
        "data": {
            "points": [{**item, "municipal_group": group_name} for group_name, group in periurbano["groups"].items() for item in group["points"]],
            "lines": [item for group in periurbano["groups"].values() for item in group["lines"]],
            "polygons": periurbano["polygons"],
        },
    }]



    # Keep raw feature attributes in the browser search index; Leaflet renders the
    # dense electrical network through a shared Canvas renderer.
    layers += [{"id":"centrality","name":"Centrality","locality":"Punta Arenas","color":"#00a6a6","data":{"points":centrality_points,"lines":[item for group in centrality["groups"].values() for item in group["lines"]],"polygons":centrality["polygons"]}}]
    layers += [{"id":"cameras","name":"Cámaras","locality":"Punta Arenas","color":"#3949ab","data":{"points":camera_points,"lines":[],"polygons":[]}}]
    for locality, filename in LOCALITY_KMZ.items():
        layers.extend(build_locality_layers(locality, filename))
    layers_bytes = json.dumps(layers, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    return base64.b64encode(gzip.compress(layers_bytes, compresslevel=6)).decode("ascii")

try:
    layers_json = build_layers_json()
except Exception as exc:
    st.error(f"No se pudieron preparar las capas: {exc}")
    st.stop()
